<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=(int)($_POST['user_id']??0);$action=(string)($_POST['action']??'');$q=$pdo->prepare('SELECT user_id,role,status FROM users WHERE user_id=?');$q->execute([$id]);$target=$q->fetch();
 if(!$target){flash('danger','User account not found.');go('admin/users.php');}
 if($id===(int)current_user()['user_id']){flash('danger','Your current administrator account is protected here.');go('admin/users.php');}
 if($action==='status'&&in_array($_POST['status']??'', ['active','inactive'],true)){
  if($target['role']==='admin'&&$target['status']==='active'&&$_POST['status']==='inactive'){$q=$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin' AND status='active'");if((int)$q->fetchColumn()<=1){flash('danger','The last active administrator cannot be deactivated.');go('admin/users.php');}}
  $q=$pdo->prepare('UPDATE users SET status=?,updated_at=NOW() WHERE user_id=?');$q->execute([$_POST['status'],$id]);flash('success','Account status updated.');
 }elseif($action==='role'&&in_array($_POST['role']??'', ['admin','user'],true)){
  if($target['role']==='admin'&&$target['status']==='active'&&$_POST['role']==='user'){$q=$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin' AND status='active'");if((int)$q->fetchColumn()<=1){flash('danger','The last active administrator cannot be demoted.');go('admin/users.php');}}
  $q=$pdo->prepare('UPDATE users SET role=?,updated_at=NOW() WHERE user_id=?');$q->execute([$_POST['role'],$id]);flash('success','User role updated.');
 }elseif($action==='delete'){
  if($target['role']==='admin'&&$target['status']==='active'){$q=$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin' AND status='active'");if((int)$q->fetchColumn()<=1){flash('danger','The last active administrator cannot be deleted.');go('admin/users.php');}}
  $q=$pdo->prepare('SELECT file_path FROM dependency_files f JOIN projects p ON p.project_id=f.project_id WHERE p.user_id=?');$q->execute([$id]);$paths=$q->fetchAll(PDO::FETCH_COLUMN);$q=$pdo->prepare('DELETE FROM users WHERE user_id=?');$q->execute([$id]);foreach($paths as $path){$full=UPLOAD_DIR.'/'.$path;if(is_file($full))@unlink($full);}flash('success','User account and associated records deleted.');
 }
 go('admin/users.php');
}
$users=$pdo->query('SELECT user_id,full_name,email,role,status,created_at FROM users ORDER BY created_at DESC')->fetchAll();page_header('User Management');?>
<div class="page-heading"><div><span class="eyebrow">ADMINISTRATION</span><h1>User Management</h1><p>Manage Developer access and account roles.</p></div></div>
<div class="card"><div class="card-header"><strong>Registered accounts</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Registered</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):$self=(int)$u['user_id']===(int)current_user()['user_id'];?><tr><td><?=e($u['full_name'])?></td><td><?=e($u['email'])?></td><td><?php if($self):?><span class="badge text-bg-primary">Current account</span><?php else:?><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><select class="form-select form-select-sm" name="role"><option value="user" <?=$u['role']==='user'?'selected':''?>>Developer</option><option value="admin" <?=$u['role']==='admin'?'selected':''?>>Administrator</option></select><button class="btn btn-sm btn-outline-primary">Save</button></form><?php endif;?></td><td><span class="badge text-bg-<?=$u['status']==='active'?'success':'secondary'?>"><?=e($u['status'])?></span></td><td><?=e($u['created_at'])?></td><td><?php if($self):?><span class="small text-secondary">Protected</span><?php else:?><div class="d-flex gap-1"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="status"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><input type="hidden" name="status" value="<?=$u['status']==='active'?'inactive':'active'?>"><button class="btn btn-sm btn-outline-secondary"><?=$u['status']==='active'?'Deactivate':'Activate'?></button></form><form method="post" onsubmit="return confirm('Delete this account and all associated projects?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require APP_ROOT.'/includes/footer.php';?>
